:root {
  --ink: #24352d;
  --paper: #fffaf0;
  --ember: #d96c3d;
  --line: #c9bfae;
}

.wood-tag {
  width: 440px;
  padding: 16px 18px;
  color: var(--ink);
  background: var(--paper);
  border: 2px solid var(--ink);
  border-radius: 14px;
}

.tag-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-bottom: 10px;
  border-bottom: 1px solid var(--line);
}

.tag-header h2 {
  margin: 0;
  font-size: 20px;
  line-height: 1;
}

.tag-header p {
  margin: 0;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 1px;
}

.wood-tag > p {
  margin: 12px 0;
  font-size: 14px;
}

.tag-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.badge {
  padding: 4px 8px;
  color: var(--paper);
  background: var(--ember);
  border-radius: 999px;
  font-size: 11px;
  font-weight: 700;
}
